package dev.zomboid.mts;
import java.util.*;import minecrafttransportsimulator.entities.instances.*;
public class WorkshopChecks {static int n;static void check(boolean b,String m){n++;if(!b)throw new AssertionError(m);}public static void main(String[]args){EntityVehicleF_Physics car=new EntityVehicleF_Physics();check(RoadPhysics.soft("minecraft:oak_leaves"),"leaves are soft");check(RoadPhysics.soft("minecraft:moss_block"),"moss is soft");check(!RoadPhysics.soft("minecraft:mossy_cobblestone"),"mossy stone remains hard");check(RoadPhysics.maximumStep(10,.5)==2,"step including wheel radius capped to 2.5");check(RoadPhysics.maximumStep(1,.5)==1,"small wheel settings preserved");check(RoadPhysics.tilt(20,0,true)==.75,"gradual pitch");check(Math.abs(RoadPhysics.tilt(20,21.8,true)-.2)<.001,"pitch capped to 22 degrees");check(RoadPhysics.tilt(20,35,false)==-.75,"old excessive roll corrected gradually");car.velocity=3;RoadPhysics.begin(car);car.world.name="minecraft:oak_leaves";check(RoadPhysics.hardness(car.world,new Checks.Point(0,0,0),car)==0,"soft obstacles break without resistance");Maintenance.collision(true,car,new Checks.Box(),true);check(car.damageVar.currentValue==0,"leaves do not damage car");RoadPhysics.begin(car);car.world.name="minecraft:stone";RoadPhysics.hardness(car.world,new Checks.Point(0,0,0),car);Maintenance.collision(true,car,new Checks.Box(),true);check(car.damageVar.currentValue>0&&car.damageVar.currentValue<=car.definition.general.health*.06,"stone damages car with prior six percent cap");check(Workshop.band(null)==3&&Workshop.band(90d)==0&&Workshop.band(50d)==1&&Workshop.band(10d)==2,"condition colours include missing part");Checks.Slot slot=new Checks.Slot();slot.types.add("ground_wheel");car.definition.parts.add(slot);car.partsInSlots.add(null);List<Workshop.Entry> rows=Workshop.equipment(car);check(rows.get(0).condition()==null,"missing wheel shown as absent, not full health");PartEngine part=new PartEngine();car.partsInSlots.set(0,part);check(Workshop.equipment(car).get(0).condition()==100,"installed part condition read from native damage");car.definition.packID="belroftmotors";car.definition.systemName="adventure";check(Mechanics.car(car),"Belroft road car integrated");car.definition.systemName="corallum";check(!Mechanics.car(car),"Belroft boat physics preserved");System.out.println("Workshop/terrain checks: "+n);}}
